<?php
require __DIR__.'/bootstrap.php'; require_login();
$user=(int)$_SESSION['user_id']; $stmt=$conn->prepare('SELECT id,asset_tag,brand,model FROM laptops WHERE assigned_to=? AND status="Assigned" ORDER BY asset_tag');$stmt->bind_param('i',$user);$stmt->execute();$assets=$stmt->get_result();
layout_start('Location check-in'); ?><div class="hero"><div><h1>Authorised location check-in</h1><p class="muted">This sends one location only after you choose an assigned device and grant browser permission. It is not continuous tracking.</p></div></div><section class="panel" style="max-width:680px"><form id="checkin"><input type="hidden" id="csrf" value="<?=csrf()?>"><label>Assigned asset<select id="asset" required><option value="">Choose an asset</option><?php while($a=$assets->fetch_assoc()):?><option value="<?=$a['id']?>"><?=e($a['asset_tag'].' — '.$a['brand'].' '.$a['model'])?></option><?php endwhile;?></select></label><label><input type="checkbox" id="consent" required> I have read the privacy notice and consent to this one-time location check-in for the selected organisation-owned asset.</label><button type="submit">Share my current location</button></form><p id="message" class="muted" aria-live="polite"></p></section><section class="panel"><h2>Privacy notice</h2><p>Only your selected asset, coordinates, accuracy, capture time, consent status, and source are stored. Authorised administrators can view the last-known location and history; their access is audited. You may refuse permission. Contact your administrator to request correction or retention review.</p></section><script>
document.getElementById('checkin').addEventListener('submit', async e => {e.preventDefault();const msg=document.getElementById('message'), asset=document.getElementById('asset').value;if(!asset||!document.getElementById('consent').checked)return; if(!navigator.geolocation){msg.textContent='This browser does not support geolocation.';return}msg.textContent='Requesting your permission…';navigator.geolocation.getCurrentPosition(async p=>{try{const r=await fetch('location_checkin_api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf:document.getElementById('csrf').value,asset_id:asset,latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy_meters:p.coords.accuracy,captured_at:new Date().toISOString(),consent:true})});const data=await r.json();msg.textContent=data.message||'Check-in saved.'}catch(_){msg.textContent='Could not save the check-in. Please try again.'}},err=>msg.textContent='Location permission was not granted: '+err.message,{enableHighAccuracy:true,timeout:15000,maximumAge:0})});
</script><?php layout_end();
